const raw = $input.first().json;
const input = (raw && raw.body && typeof raw.body === 'object' && Object.keys(raw.body).length > 0) ? raw.body : raw;

const isScheduledTrigger = Boolean(raw && (raw.timestamp || raw.readableSchedule || raw.rule));
const eventType = isScheduledTrigger ? 'SCAN_DUE_TASKS' : (input.event_type || input.task_type || 'TASK_EVALUATION');

const taskId = input.task_id || 'tsk-mock-' + Date.now();
const taskCode = input.task_code || 'TSK-' + Math.random().toString(36).substring(2, 8).toUpperCase();
const taskType = input.task_type || 'ADMINISTRATIVE';
const title = input.title || 'Compromiso operativo pendiente';
const orgId = input.organization_id || '00000000-0000-0000-0000-000000000001';
const assignedUserId = input.assigned_user_id || null;
const assignedUserName = input.assigned_user_name || input.staff_name || 'Personal Asignado';
const priority = input.priority || 'STANDARD';
const workStatus = input.work_status || 'CREATED';
const dueAt = input.due_at || new Date(Date.now() + 3600000).toISOString();
const requiresEvidence = input.requires_evidence === true;
const isClinicallySensitive = input.is_clinically_sensitive === true;

// Reglas de urgencia y severidad
const isStaffAbsence = taskType === 'STAFF_ABSENCE_ALERT' || input.is_urgent_replacement_required === true || (input.affected_appointments_count || 0) > 0;
const isOverdue = new Date(dueAt).getTime() <= Date.now() && !['COMPLETED', 'VERIFIED', 'CANCELLED'].includes(workStatus);
const isUrgent = isStaffAbsence || priority === 'URGENT_P0' || isOverdue;

let actionDecision = 'ENQUEUE_ROUTINE_REMINDER';
let dispatchChannel = 'STAFF_DAILY_DIGEST';
let reminderTemplate = 'vet_internal_task_reminder';

if (isStaffAbsence) {
  actionDecision = 'TRIGGER_SHIFT_REPLACEMENT_WORKFLOW';
  dispatchChannel = 'COORDINATOR_DASHBOARD_AND_PUSH';
  reminderTemplate = 'vet_urgent_staff_absence';
} else if (isOverdue) {
  actionDecision = 'ESCALATE_OVERDUE_TASK';
  dispatchChannel = 'COORDINATOR_ESCALATION';
  reminderTemplate = 'vet_task_overdue_warning';
} else if (workStatus === 'WAITING_ACCEPTANCE' || workStatus === 'ASSIGNED') {
  actionDecision = 'REQUEST_TASK_ACCEPTANCE';
  dispatchChannel = 'IN_APP_NOTIFICATION';
  reminderTemplate = 'vet_task_acceptance_request';
} else if (workStatus === 'PENDING_VERIFICATION') {
  actionDecision = 'REQUEST_VERIFICATION_GATE';
  dispatchChannel = 'CLINICAL_COORDINATOR_REVIEW';
  reminderTemplate = 'vet_task_verification_required';
}

return {
  json: {
    event_type: eventType,
    task_id: taskId,
    task_code: taskCode,
    task_type: taskType,
    title: title,
    organization_id: orgId,
    assigned_user_id: assignedUserId,
    assigned_user_name: assignedUserName,
    owner_team: input.owner_team || 'COORDINATION',
    priority: priority,
    work_status: workStatus,
    due_at: dueAt,
    is_urgent_action_required: isUrgent,
    is_staff_absence: isStaffAbsence,
    is_overdue: isOverdue,
    requires_evidence: requiresEvidence,
    is_clinically_sensitive: isClinicallySensitive,
    action_decision: actionDecision,
    dispatch_channel: dispatchChannel,
    reminder_template: reminderTemplate,
    core_03_dispatch_request: {
      message_category: 'UTILITY',
      message_purpose: 'OPERATIONAL_REMINDER',
      target_user: assignedUserName,
      template_code: reminderTemplate,
      idempotency_key: 'ops-rem-' + taskId + '-' + new Date().toISOString().replace(/[^0-9]/g, '').substring(0, 14),
      send_enabled: false
    },
    send_enabled: false,
    evaluated_at: new Date().toISOString()
  }
};
